SET @cat = (SELECT id FROM categories WHERE name = 'Study');

INSERT IGNORE INTO quest_templates
    (category_id, track, quest_type, title, summary, description, why, difficulty, time_limit_hours)
VALUES
-- Main quests
(@cat,'reading','main','Finish a book in three weeks','Read one complete book within 21 days','Choose a book you want to read or need to read and finish it within 21 days. Work out how many pages you need each day and keep to it. Missing a day is fine as long as you catch up.','Finishing a whole book builds the stamina to handle long, difficult material.','medium',504),
(@cat,'focus','main','Study 30 minutes a day for two weeks','Study for at least 30 minutes on 12 of 14 days','Pick one subject or goal and study it for at least 30 minutes on 12 of the next 14 days. Tick off each day. Short sessions done daily beat long sessions done rarely.','Small daily sessions turn studying from a chore into a habit that sticks.','medium',336),
(@cat,'writing','main','Write a 1500-word piece','Complete an essay, report or article of 1500 words','Choose a topic, plan an outline, write a full draft and then edit it. Your finished piece must be at least 1500 words and completed within 14 days.','Writing forces you to organise your thoughts, which is the fastest way to find what you do not yet understand.','hard',336),
(@cat,'skills','main','Spend 30 days learning one new skill','Practise one skill for 20 minutes on 25 of 30 days','Pick one skill, such as a language, an instrument, coding or drawing. Practise it for at least 20 minutes on 25 of the next 30 days and note what you can do at the end that you could not at the start.','Thirty days of steady practice is enough to see real progress in almost any skill.','epic',720),
(@cat,'revision','main','Complete a full revision cycle','Revise one topic from notes to practice questions to retest','Pick one topic. Review your notes, make a one-page summary, create flashcards, do practice questions and retest yourself at the end. All stages must be finished within 14 days.','Revision that includes testing yourself beats simply rereading by a large margin.','hard',336),
(@cat,'focus','main','Seven phone-free study sessions','Study for 45 minutes with your phone out of reach, seven times','Complete seven study sessions of at least 45 minutes with your phone in another room or switched off. They can be spread across the next seven days.','Removing the phone is the single biggest boost to real concentration.','medium',168),
(@cat,'memory','main','Learn 100 flashcards','Create and learn 100 flashcards over 21 days','Make 100 flashcards on a topic you need to remember. Review them regularly over 21 days, and by the end you should answer at least 80 correctly from memory.','Spaced review is how information moves from short-term to long-term memory.','hard',504),
(@cat,'skills','main','Finish an online course','Complete every lesson of one short online course','Choose a short free or paid online course and complete all its lessons within 30 days, including any quizzes or exercises.','Finishing a course proves you can follow a structured plan through to the end.','epic',720),

-- Side quests: reading
(@cat,'reading','side','Read for 30 minutes','Read a book or long article for half an hour','Put your phone away and read something you chose for 30 minutes in one sitting.','Daily reading builds vocabulary, focus and general knowledge.','easy',24),
(@cat,'reading','side','Read 20 pages','Read 20 pages of a book','Read 20 pages of any book you are working through, wherever you like.','Small page targets make a long book feel manageable.','easy',24),
(@cat,'reading','side','Read a long article and summarise it','Read a long article and write a three-sentence summary','Read a long article from a trusted source, then write a three-sentence summary in your own words.','Summarising proves whether you actually understood what you read.','medium',24),
(@cat,'reading','side','Read for 45 minutes without interruption','Read with no phone and no breaks for 45 minutes','Silence notifications and read for 45 minutes in one go.','Uninterrupted reading is rare now and trains deep concentration.','medium',24),
(@cat,'reading','side','Read a chapter and note three ideas','Read one chapter and write down three key ideas','Read a full chapter and note down the three most important ideas.','Noting key ideas helps you remember what you read.','medium',24),
(@cat,'reading','side','Read outside your usual topics','Read an article on a subject you rarely read about','Choose a topic far from your usual interests and read one good article about it.','Wider reading helps you connect ideas across different subjects.','easy',48),

-- Side quests: writing
(@cat,'writing','side','Write a short reflection','Write 100 words on what you learned today','At the end of the day write at least 100 words about what you learned and what is still unclear.','Reflecting on a lesson strengthens your memory of it.','easy',24),
(@cat,'writing','side','Summarise a lesson in 150 words','Condense one lesson into 150 words','Take one lesson or lecture and summarise it in about 150 words without looking at your notes.','Writing from memory shows you exactly what you know.','easy',24),
(@cat,'writing','side','Write a 500-word draft','Draft 500 words on any topic you are studying','Set a timer and write 500 words on one topic, ignoring editing until the end.','A messy first draft is far easier to improve than a blank page.','medium',24),
(@cat,'writing','side','Rewrite your notes more clearly','Turn messy notes into a clean version','Take notes from one lesson and rewrite them clearly, adding headings and examples.','Rewriting forces you to process the material again.','medium',24),
(@cat,'writing','side','Write and answer three questions','Create three exam-style questions and answer them','Write three questions on a topic you are studying, then answer them without looking at your notes.','Questioning yourself is one of the best ways to learn.','easy',24),

-- Side quests: focus
(@cat,'focus','side','One 25-minute focus session','Work on one task for 25 minutes without stopping','Set a timer for 25 minutes, work on a single task and ignore everything else.','Short timed sessions make starting easier and keep your attention sharp.','easy',24),
(@cat,'focus','side','Two focus sessions with a break','Complete two 25-minute sessions with a 5-minute break','Do two focused 25-minute sessions with a five minute break between them.','Alternating work and rest lets you concentrate for longer overall.','medium',24),
(@cat,'focus','side','Study with your phone in another room','Study for 30 minutes with no phone nearby','Leave your phone in another room and study for 30 minutes.','Even a silent phone on the desk drains concentration.','easy',24),
(@cat,'focus','side','Clear your desk before studying','Tidy your workspace before you start','Take five minutes to clear your desk of everything you do not need, then start studying.','A clear space makes it easier to begin and harder to get distracted.','easy',24),
(@cat,'focus','side','One hour with a short break','Study for one hour with a five-minute break halfway','Study for 30 minutes, break for five, then study for 30 more.','A one hour block is long enough to make real progress on a hard task.','medium',24),
(@cat,'focus','side','45-minute deep work block','Work on one hard task for 45 minutes without interruption','Choose your hardest task, close everything else and work on it for 45 minutes.','Deep work on difficult material is where most of your learning happens.','medium',24),

-- Side quests: revision
(@cat,'revision','side','Review the notes from yesterday','Spend 15 minutes on yesterdays notes','Spend 15 minutes reading through the notes you made yesterday.','A quick review the next day stops you forgetting most of what you learned.','easy',24),
(@cat,'revision','side','Do 10 practice questions','Answer ten practice questions on a topic','Find ten practice questions on a topic you are studying and answer them.','Practice questions show you what you can really do.','easy',24),
(@cat,'revision','side','Timed practice section','Answer a practice paper section under time pressure','Take a section of a past paper or practice test and complete it within the real time limit.','Practising under time pressure prepares you for the real thing.','medium',24),
(@cat,'revision','side','Make a one-page summary','Condense a whole topic onto a single page','Summarise one entire topic on a single page using headings, keywords and diagrams.','A one-page summary is the best thing to review just before a test.','medium',24),
(@cat,'revision','side','Teach a concept out loud','Explain one concept aloud for five minutes','Explain a concept out loud as if teaching a beginner, with no notes.','If you cannot explain it simply, you do not understand it yet.','easy',24),
(@cat,'revision','side','Fix three past mistakes','Find three old mistakes and learn the correct answers','Look at past work, find three mistakes and write out the correct method for each.','Learning from mistakes is faster than learning from scratch.','medium',48),

-- Side quests: memory
(@cat,'memory','side','Make 15 flashcards','Create fifteen flashcards on one topic','Write fifteen flashcards, each with a question on one side and the answer on the other.','Making cards is already a first round of learning.','easy',24),
(@cat,'memory','side','Review 30 flashcards','Go through thirty cards, separating known from unknown','Go through thirty flashcards and sort them into those you knew and those you did not.','Reviewing what you got wrong is where the learning happens.','easy',24),
(@cat,'memory','side','Recall a topic from memory','Write down everything you remember, then check','Pick a topic, write everything you remember about it, then check your notes for gaps.','Pulling information out of memory strengthens it more than rereading.','medium',24),
(@cat,'memory','side','Learn 10 new terms','Learn ten key terms or vocabulary words','Choose ten key terms or words and learn their meanings well enough to use them.','A strong vocabulary makes every subject easier to follow.','easy',24),

-- Side quests: planning
(@cat,'planning','side','Plan tomorrow in ten minutes','Write your study plan for tomorrow','Spend ten minutes choosing what you will study tomorrow and when.','Knowing what to do before you start removes the biggest barrier to starting.','easy',24),
(@cat,'planning','side','Choose three priorities for the week','List the three most important study tasks this week','Write down the three most important study tasks for the week ahead and place them in your calendar.','Choosing a few priorities stops you doing easy work instead of important work.','easy',24),
(@cat,'planning','side','Break an assignment into steps','Split a big assignment into small tasks with dates','Take a big assignment and break it into smaller tasks, giving each a date.','Small steps are far less frightening than one huge task.','medium',24),
(@cat,'planning','side','Organise your digital notes','Tidy and name your files and folders','Spend time sorting your digital notes into clear folders with sensible names.','Organised notes are easy to find when you need them most.','easy',48),

-- Side quests: skills
(@cat,'skills','side','Watch a tutorial and try it','Learn something from a video and apply it straight away','Watch a short tutorial on something you want to learn, then try it yourself straight afterwards.','Trying something right after learning it makes it stick.','medium',24),
(@cat,'skills','side','Practise a skill for 30 minutes','Spend half an hour on a skill you are building','Choose a skill you are learning and practise it deliberately for 30 minutes.','Regular short practice beats occasional long practice.','easy',24),
(@cat,'skills','side','Complete one online lesson','Finish a single lesson of an online course','Complete one full lesson of an online course, including any exercise.','One lesson at a time is how courses get finished.','easy',24),
(@cat,'skills','side','Make something small','Build or create something using what you recently learned','Use something you learned recently to make a small project, such as a program, a drawing or a short piece of writing.','Making something is the real test of whether you learned it.','medium',48),
(@cat,'skills','side','Solve a problem you have been avoiding','Tackle one hard problem you keep putting off','Choose a problem you have been avoiding and work on it for at least 30 minutes.','The task you avoid is usually the one that matters most.','medium',48),

-- Bonus quests
(@cat,'focus','bonus','Study somewhere new','Change location for a study session','Study for at least 30 minutes in a place you have not studied before.','A new setting can bring fresh focus.','easy',24),
(@cat,'focus','bonus','Study with a friend for an hour','Work side by side with someone for an hour','Invite a friend to study with you, in person or online, for an hour.','Studying alongside someone keeps both of you accountable.','easy',48),
(@cat,'reading','bonus','Ask a question you have been holding back','Ask a teacher, tutor or friend something you were unsure about','Ask the question you have been too shy to ask.','Most people have the same question and are glad someone asked it.','easy',48),
(@cat,'reading','bonus','Visit a library','Spend time in a library or study space','Go to a library, even for 30 minutes, and read or study there.','Libraries are built for focus and have resources you may not have thought of.','easy',48),
(@cat,'skills','bonus','Listen to an educational podcast','Listen to an episode about a topic you want to understand','Listen to a full episode of an educational podcast.','Passive time can become learning time.','easy',24),
(@cat,'skills','bonus','Watch a documentary on a new topic','Watch a documentary about something unfamiliar','Choose a documentary on a topic you know little about and watch it all.','Broad knowledge makes your main subjects easier to understand.','medium',48),
(@cat,'revision','bonus','Explain what you learned to someone','Teach someone one thing you learned recently','Explain something you learned recently to a friend or family member.','Teaching is the quickest way to find the gaps in your understanding.','easy',24),
(@cat,'reading','bonus','Read about someone who inspires you','Read a short biography or profile','Read about the life of someone whose work you admire.','Stories of people who succeeded can make hard work feel worthwhile.','easy',24),
(@cat,'revision','bonus','Try a new study technique','Test a method you have not used before','Try a technique such as the Feynman method, mind mapping or active recall.','Finding a technique that suits you saves hours in the long run.','medium',48),
(@cat,'focus','bonus','Create a focus playlist','Put together a playlist and use it while studying','Make a playlist of calm music without lyrics and use it during one study session.','A consistent audio cue helps your brain switch into study mode.','easy',24),
(@cat,'revision','bonus','Review notes for ten minutes before bed','Read through the days notes before sleeping','Spend ten minutes reading the days notes just before bed.','Sleeping soon after reviewing helps your brain store what you learned.','easy',24),
(@cat,'skills','bonus','Learn a word in another language','Learn one new word or phrase in a language you like','Learn a new word or phrase in another language and use it in a sentence.','Small daily language gains add up over time.','easy',24),
(@cat,'skills','bonus','Find a free course on a topic you want','Search for a course that interests you','Look up free courses on a topic you want to learn and pick one for the future.','Having a next goal ready keeps your momentum going.','easy',48),
(@cat,'writing','bonus','Handwrite your notes for a day','Use pen and paper for all your notes today','Take all your notes by hand today instead of typing them.','Handwriting slows you down just enough to process what you hear.','easy',24),
(@cat,'writing','bonus','Thank a teacher or mentor','Write a short note of thanks','Write a short, honest thank-you message to someone who has helped you learn.','Gratitude strengthens the relationships that support your learning.','easy',48),
(@cat,'planning','bonus','Reflect on your week of study','Write what went well and what to change','Write a short note on what went well this week and one thing to improve next week.','Regular reflection is how you get better at studying itself.','easy',48);